var INDUSTRIA=[{n:"DePuy Synthes — ATTUNE Revision Hinge Knee",v:"Nessun aggiornamento oggi. Il richiamo openFDA (componenti hinge, confezione sterile esterna aderente all'interna) resta aperto, classificato — riconfermato dal raccoglitore notturno di stanotte."},{n:"Zimmer Biomet — ciotole e spatole in kit Medline TOTAL KNEE PACK",v:"Nessun aggiornamento oggi. Il richiamo openFDA (non conformità della saldatura, rischio di rottura della sterilità) resta aperto, classificato — riconfermato dal raccoglitore notturno di stanotte."},{n:"Encore Medical / Enovis — EMPOWR 3D KNEE",v:"Richiamo openFDA emerso per la prima volta nel nostro monitoraggio stanotte (avviato il 15 luglio 2026, Classe II): discrepanza di imballaggio con scambio di taglie del componente inserto tibiale. Nessun problema di sterilità o di funzionamento del dispositivo dichiarato — rischio di natura logistica (taglia sbagliata in sala), non un rischio clinico diretto per il paziente."}];
